import Foundation

/// Builds a `.command` script that runs update commands in Terminal. The
/// script deliberately keeps prompts possible: Terminal owns the TTY and the
/// password, while Remige never sees either.
public enum UpgradeTerminalScript {
    public static func make(items: [OutdatedItem]) -> String? {
        var seen = Set<CommandSpec>()
        let commands = items.compactMap(UpgradeCommand.spec).filter { seen.insert($0).inserted }
        guard !commands.isEmpty else { return nil }

        var lines = [
            "#!/bin/zsh",
            "# Generated by Remige. These updates need a terminal for input.",
            "cd \"$HOME\"",
            "export PATH=\(ShellQuote.word(EnvironmentSnapshot.path()))",
        ]
        for key in UpgradeCommand.terminalEnvironment.keys.sorted() {
            lines.append(
                "export \(key)=\(ShellQuote.word(UpgradeCommand.terminalEnvironment[key] ?? ""))"
            )
        }
        lines += [
            "",
            "failures=0",
            "run_update() {",
            "  echo",
            "  echo \"→ $*\"",
            "  \"$@\"",
            "  local code=$?",
            "  if [ \"$code\" -ne 0 ]; then",
            "    failures=$((failures + 1))",
            "    echo \"✗ exit $code\"",
            "  fi",
            "}",
            "",
        ]
        for command in commands {
            let argv = ([command.executable] + command.arguments).map(ShellQuote.word)
            lines.append("run_update \(argv.joined(separator: " "))")
        }
        lines += [
            "",
            "echo",
            "if [ \"$failures\" -eq 0 ]; then",
            "  echo \"✓ All updates finished.\"",
            "else",
            "  echo \"✗ $failures update(s) failed.\"",
            "fi",
            "printf '\\nPress Return to close this window...'",
            "read -r _",
            "exit \"$failures\"",
            "",
        ]
        return lines.joined(separator: "\n")
    }
}
